vec3 camera_pos = vec3 ( sin ( iTime ), 0 ., cos ( iTime ) + forward );

vec2 projected_pos = camera_pos . xy / camera_pos . z ;

c = iForeground * step ( length ( uv - projected_pos ), radius );

